xs = np.arange(len(lab)); a1.bar(xs - 0.2, v1, 0.4, label="One-sided", color="#7f7f7f"); a1.bar(xs + 0.2, v2, 0.4, label="Two-sided", color="#2a6f97"); a1.axhline(0.5, color="k", lw=0.6, ls="--")
a1.set_xticks(xs); a1.set_xticklabels(lab, fontsize=8); a1.set_ylabel("AUC"); a1.set_title("a  Sentence mixing (50%)", fontsize=9, loc="left"); a1.legend(fontsize=7, frameon=False); a1.set_ylim(0, 1)
ac_ = pd.read_csv(f"{D}/artifact_control_results.csv"); acq = ac_[ac_.protocol == "unseen-generator"].pivot_table(index="generator", columns="variant", values="auc").loc[["claude", "gpt4o", "llama"], ["raw", "clean", "function"]]
