fm = lambda x: "–" if pd.isna(x) else f"{x:.2f}"
# ---- tables
def cell(dk, g):
    r = M.loc[(dk, g)]; o = r.get("orig"); atk = r[[c for c in CONDS[1:] if c in r.index and not pd.isna(r[c])]]
    w = atk.idxmin(); return f"{o:.2f} → {atk[w]:.2f} ({CLAB[w].lower()})"
T2 = [["Detector"] + [gl for _, gl in GENS]] + [[n] + [cell(dk, g) for g, _ in GENS] for dk, n in DET]
T1 = [["Detector"] + [gl for _, gl in GENS] + ["Cost per document"]]
cost = {"screen_baseline": "ms, CPU", "screen_clustering": "ms, CPU", "loglik": "GPU, 7B model", "logrank": "GPU, 7B model", "binoculars": "GPU, two 7B models", "fastdetect": "GPU, two 7B models",
        "tfidf": "ms, CPU (needs labels)", "roberta": "GPU fine-tuning (needs labels)", "gemini": "US$0.017, 23 s"}
for dk, n in DET: T1.append([n] + [fm(M.loc[(dk, g)]["orig"]) for g, _ in GENS] + [cost[dk]])
ac = pd.read_csv(f"{D}/artifact_control_results.csv"); acp = ac.pivot_table(index=["protocol", "generator"], columns="variant", values="auc")
T3 = [["Protocol", "Generator", "Raw text", "Artifacts removed", "Function words only"]]
for (pr, g), r in acp.iterrows(): T3.append([{"grouped-cv": "Same generator in training", "unseen-generator": "Unseen generator"}[pr], dict(GENS)[g], fm(r["raw"]), fm(r["clean"]), fm(r["function"])])
sr = json.load(open(f"{D}/screen_results.json"))
# two-sided check for probability detectors
b = pd.read_csv(f"{D}/attacked2_binoculars.csv"); b["cond"] = b.id.str.split("|").str[-1]; neg = b[b.cond == "clean"]
def two(m, g, c):
    x = pd.concat([neg, b[(b.generator == g) & (b.cond == c)]]); med = neg[m].median()
    return roc_auc_score(x.label, x[m]), roc_auc_score(x.label, (x[m] - med).abs())
l1, l2 = two("loglik", "claude", "mix50"); e1, e2 = two("entropy", "claude", "mix50"); g1, g2 = two("loglik", "gpt4o", "mix50")
mu_h = neg.loglik.mean(); mu_c = b[(b.generator == "claude") & (b.cond == "mix50")].loglik.mean()
ju = J.set_index(["generator", "cond"])
print("two-sided", l1, l2, e1, e2, g1, g2, mu_h, mu_c)

